AWS API Gateway / NLB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_api_gateway_nlb, "AWS API Gateway / NLB") {
    Component(AWS_Network_Load_Balancer, "AWS Network Load Balancer", "AWS NLB", "Forwards raw incoming traffic securely via TCP/TLS.")
    Component(AWS_WAF, "AWS WAF", "AWS WAF", "Inspects and filters incoming HTTP traffic for malicious requests.")
    Component(AWS_API_Gateway, "AWS API Gateway", "AWS API Gateway (HTTP API)", "Decapsulates requests and routes them to downstream internal services via VPC Link.")
}

Rel(AWS_Network_Load_Balancer, AWS_WAF, "Forwards traffic for security inspection")
Rel(AWS_WAF, AWS_API_Gateway, "Forwards filtered requests")

@enduml

Tamper-Evident Storage.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Tamper-Evident Storage", "Tamper-Evident Storage") {
    Component("Audit Logger", "Audit Logger", "AWS Lambda / Worker", "Appends immutable decision logs to tamper-evident storage.")
    Component("Tamper-Evident Storage", "Tamper-Evident Storage", "Amazon S3 with Object Lock in Compliance Mode", "WORM storage guaranteeing 7-year tamper-evident retention.")
}

Rel("Audit Logger", "Tamper-Evident Storage", "Appends immutable decision logs", "HTTPS / S3 API via VPC Endpoint")

@enduml

Message Queue.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Message Queue container

Container_Boundary(message_queue, "Message Queue") {
    Component(fraud_decisions_queue, "fraud-decisions-queue", "Amazon SQS with AWS KMS encryption", "Main asynchronous message queue for publishing fraud decision payloads.")
    Component(fraud_decisions_dlq, "fraud-decisions-dlq", "Amazon SQS with AWS KMS encryption", "Dead-letter queue for handling failed decision payload processing attempts.")
}

Rel(fraud_decisions_queue, fraud_decisions_dlq, "Routes unprocessable or failed messages after maximum retries", "")

@enduml
